from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t < wt + ttl:
                    # still valid, just update value/time and move to most-recently-used
                    cache.pop(key)
                    cache[key] = (value, t)
                    continue
                else:
                    # expired, treat as absent
                    cache.pop(key)
            # key not present (either wasn't there or just expired)
            if len(cache) >= capacity:
                cache.popitem(last=False)  # evict LRU
            cache[key] = (value, t)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t < wt + ttl:
                    # valid, move to most-recently-used, keep same write time
                    cache.pop(key)
                    cache[key] = (v, wt)
                    results.append(v)
                else:
                    # expired
                    cache.pop(key)
                    results.append(-1)
            else:
                results.append(-1)
    return results

